// This file is generated by AI.

// 从训练切分产物导入角色。
//
// 交互刻意做成**一个对话框 + 两个路径输入框**:
// 之前是"依次弹出两个系统目录选择框", 用户点完第一个还要再点第二个, 中间没有任何
// 反馈, 很容易以为操作已经结束。这里把两个路径都摆在面前, 各自配一个文件夹图标,
// 一次点"导入"即可。
//
// 导入条数**不设上限**, 但**条数很多时会先停下来问一句**: 每段音频都要拷贝进角色库
// 并逐个解码规范化, 一次导入几千条既慢又占空间, 而用户往往并不知道自己选的那份清单
// 有多大。数字由后端预览给出 (与真正导入是同一套解析), 因此不存在"提示与实际不符"。

import { Button, Field, Input } from '@fluentui/react-components';
import { FolderRegular } from '@fluentui/react-icons';
import { open as openDialog } from '@tauri-apps/plugin-dialog';
import { useState } from 'react';

import type { ListImportPreview } from '../commands/voice';
import { voicePreviewImport } from '../commands/voice';
import { AppDialog } from '../components/AppDialog';
import { voiceController } from './controller';

/**
 * 超过这个条数就先确认一次。
 *
 * 300 是"一个人配一部戏的常规语料量级"的上界: 到这个量级, 导入已经要花上一两分钟,
 * 复制进角色库的音频也可能上百 MB, 值得让用户知道自己选了什么。
 */
const CONFIRM_THRESHOLD = 300;

/** 预览里最多逐个列出的角色数 (再多就只给总数) */
const PREVIEW_NAMES = 12;

interface Props {
  onClose: () => void;
  onImported: (message: string) => void;
}

export function ListImportDialog({ onClose, onImported }: Props) {
  const [listPath, setListPath] = useState('');
  const [audioDir, setAudioDir] = useState('');
  const [busy, setBusy] = useState(false);
  /** 已取得的预览 (仅当条数超过阈值时才需要用户再看一眼) */
  const [preview, setPreview] = useState<ListImportPreview | null>(null);
  /**
   * 报错**就地显示**。
   *
   * 之前是把错误交给外层的角色面板 (调用方的 `onError`), 而这个对话框是模态的 ——
   * 用户看不到身后那块面板, 于是"导入失败"表现为"点了没反应"。出错的地方就在眼前,
   * 错误就应该出现在眼前。
   */
  const [error, setError] = useState<string | null>(null);

  const pickList = async () => {
    const picked = await openDialog({
      multiple: false,
      title: '选择清单文件',
      filters: [{ name: '文本清单', extensions: ['list', 'txt'] }],
    });
    if (typeof picked === 'string') {
      setListPath(picked);
      setPreview(null);
      setError(null);
    }
  };

  const pickAudioDir = async () => {
    const picked = await openDialog({ directory: true, multiple: false, title: '选择音频目录' });
    if (typeof picked === 'string') {
      setAudioDir(picked);
      setPreview(null);
      setError(null);
    }
  };

  const ready = listPath.trim().length > 0 && audioDir.trim().length > 0 && !busy;

  const importNow = async () => {
    const report = await voiceController.importFromList(listPath.trim(), audioDir.trim());
    onImported(
      `已导入 ${report.imported} 条参考音频，涉及 ${report.characters.length} 个角色` +
        (report.autoTrimmed > 0 ? `，其中 ${report.autoTrimmed} 条过长已自动裁剪` : '') +
        (report.skipped > 0 ? `，跳过 ${report.skipped} 条（音频缺失或无法读取）` : '') +
        (report.paired > 0 ? `，已按名称自动配对 ${report.paired} 个角色的 GSOV 模型` : '')
    );
    onClose();
  };

  /** 第一次点"导入"先取预览; 条数多则停下来确认, 否则直接导入 */
  const confirm = async () => {
    if (!ready) return;
    setBusy(true);
    setError(null);
    try {
      if (!preview) {
        const result = await voicePreviewImport(listPath.trim(), audioDir.trim());
        if (result.matched > CONFIRM_THRESHOLD) {
          setPreview(result);
          return;
        }
      }
      await importNow();
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : String(caught));
    } finally {
      setBusy(false);
    }
  };

  return (
    <AppDialog
      title="从清单导入角色"
      description="选择训练切分产物里的清单文件与音频目录。匹配按**文件名**进行，因此两者放在哪里都可以。"
      size="medium"
      height={preview ? 440 : 360}
      onClose={onClose}
      footer={
        preview ? (
          <>
            <Button appearance="secondary" disabled={busy} onClick={() => setPreview(null)}>
              返回
            </Button>
            <Button appearance="primary" disabled={busy} onClick={() => void confirm()}>
              {busy ? '导入中…' : `继续导入（${preview.matched} 条）`}
            </Button>
          </>
        ) : (
          <>
            <Button appearance="secondary" disabled={busy} onClick={onClose}>
              取消
            </Button>
            <Button appearance="primary" disabled={!ready} onClick={() => void confirm()}>
              {busy ? '处理中…' : '导入'}
            </Button>
          </>
        )
      }
    >
      <Field label="清单文件（.list）">
        <div className="workbench-input-row">
          <Input
            value={listPath}
            readOnly
            placeholder="选择包含 路径|说话者|语言|文本 的 .list 文件"
            title={listPath}
          />
          <Button
            appearance="secondary"
            icon={<FolderRegular />}
            title="选择清单文件"
            disabled={busy}
            onClick={() => void pickList()}
          />
        </div>
      </Field>

      <Field label="音频目录">
        <div className="workbench-input-row">
          <Input value={audioDir} readOnly placeholder="选择存放切分音频的目录（可嵌套子目录）" title={audioDir} />
          <Button
            appearance="secondary"
            icon={<FolderRegular />}
            title="选择音频目录"
            disabled={busy}
            onClick={() => void pickAudioDir()}
          />
        </div>
      </Field>

      {preview ? (
        <div className="import-preview">
          <p className="voice-dialog-hint">
            将导入 <b>{preview.matched}</b> 条参考音频，涉及 {preview.characters.length} 个角色
            {preview.records > preview.matched &&
              `（清单里另有 ${preview.records - preview.matched} 条在音频目录中找不到，会跳过）`}
            。
          </p>
          <ul className="import-preview-list">
            {preview.characters.slice(0, PREVIEW_NAMES).map((item) => (
              <li key={item.name}>
                {item.name} · {item.count} 条
              </li>
            ))}
            {preview.characters.length > PREVIEW_NAMES && <li>…等 {preview.characters.length} 个角色</li>}
          </ul>
          <p className="voice-dialog-hint">
            数量较多：每段音频都会被拷贝进角色库并逐个规范化，可能要花上几分钟并占用相应磁盘空间。
          </p>
        </div>
      ) : (
        <p className="voice-dialog-hint">过短的音频会在尾部补静音，过长的会按静音边界裁剪；导入条数不受限制。</p>
      )}

      {error && <p className="voice-error">{error}</p>}
    </AppDialog>
  );
}
